import { invariant, sleep } from "~/shared/util"
import type { ProgressData } from "~/components/LoadingIndicator"
import type { Route } from "./+types/api.progress"
import { loadViewSearchParams, viewSearchParamsConfig } from "~/shared/viewParams"
import { AnalysisManager } from "~/server/AnalysisManager"
import { createSerializer, parseAsInteger } from "nuqs"
import { createLoader } from "nuqs/server"

const POLLING_RATE = 1000
const LONG_POLL_TIMEOUT = 30000

const progressSearchParamsConfig = {
  path: viewSearchParamsConfig.path,
  branch: viewSearchParamsConfig.branch,
  lastSeenRevision: parseAsInteger.withDefault(-1)
}

export const progressSerializer = createSerializer(progressSearchParamsConfig)

const loadProgressSearchParams = createLoader(progressSearchParamsConfig)

export const loader = async ({ request }: Route.LoaderArgs) => {
  const { path: repositoryPath, branch } = loadViewSearchParams(request)
  invariant(repositoryPath, "path is required")
  invariant(branch, "branch is required")

  const { lastSeenRevision } = loadProgressSearchParams(request)

  const instanceIsAborted = AnalysisManager.getInstanceIsAborted({ repositoryPath, branch })
  if (instanceIsAborted) {
    return {
      progress: 0,
      analysisStatus: "Aborted" as const,
      progressRevision: -1
    } satisfies ProgressData
  }

  const progressData = AnalysisManager.getInstanceProgress({ repositoryPath, branch })
  if (!progressData) {
    return
  }

  // If we already have a newer revision, return immediately
  if (progressData.progressRevision > lastSeenRevision) {
    return {
      progress: progressData.progressPercentage,
      analysisStatus: progressData.status,
      progressRevision: progressData.progressRevision
    } satisfies ProgressData
  }

  // Otherwise, long-poll until revision changes or timeout
  const startTime = Date.now()
  while (Date.now() - startTime < LONG_POLL_TIMEOUT && !request.signal.aborted) {
    try {
      await sleep(POLLING_RATE, { signal: request.signal })
    } catch {
      return
    }
    if (request.signal.aborted) {
      return
    }

    const updatedProgress = AnalysisManager.getInstanceProgress({ repositoryPath, branch })
    if (!updatedProgress) {
      return
    }
    if (updatedProgress.progressRevision > lastSeenRevision) {
      return {
        progress: updatedProgress.progressPercentage,
        analysisStatus: updatedProgress.status,
        progressRevision: updatedProgress.progressRevision
      } satisfies ProgressData
    }
  }

  // Timeout reached, return current state
  const finalProgress = AnalysisManager.getInstanceProgress({ repositoryPath, branch })

  if (!finalProgress) {
    return
  }

  return {
    progress: finalProgress.progressPercentage,
    analysisStatus: finalProgress.status,
    progressRevision: finalProgress.progressRevision
  } satisfies ProgressData
}

import { CheckboxWithLabel } from "~/components/modals/utils/CheckboxWithLabel"
import { getDefaultOptionsContextValue, useOptions } from "~/contexts/OptionsContext"
import { Icon } from "~/components/Icon"
import { mdiClockEdit, mdiCog, mdiContentCut, mdiFileTree, mdiFilter, mdiLabel, mdiLink, mdiTransition } from "@mdi/js"
import { useState, useTransition } from "react"
import { relatedSizeMetric } from "~/components/Options"
import { Modal } from "~/components/modals/Modal"
import { ClearCacheForm } from "~/routes/clear-cache"

export function SettingsModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const {
    metricType,
    hierarchyType,
    transitionsEnabled,
    showFilesWithoutChanges,
    linkMetricAndSizeMetric,
    showOnlySearchMatches,
    setLinkMetricAndSizeMetric,
    setTransitionsEnabled,
    labelsVisible,
    setLabelsVisible,
    setHierarchyType,
    setSizeMetricType,
    setShowFilesWithoutChanges,
    setShowOnlySearchMatches
  } = useOptions()

  return (
    <Modal open={open} title="Settings" icon={mdiCog} onClose={onClose}>
      <div className="flex min-h-0 max-w-max flex-col items-start gap-3 overflow-y-auto p-2 pl-0">
        <CheckboxWithLabel
          className="group w-full text-sm hover:text-blue-500 hover:opacity-100"
          checked={Boolean(linkMetricAndSizeMetric)}
          title="Enable to sync size metric with color metric"
          onChange={(e) => {
            setLinkMetricAndSizeMetric(e.target.checked)
            if (e.target.checked) {
              setSizeMetricType(relatedSizeMetric[metricType])
            }
          }}
        >
          <Icon className="ml-1.5" path={mdiLink} size="1.25em" />
          <span className="flex-1">Link size and color option</span>
        </CheckboxWithLabel>
        <CheckboxWithLabel
          className="group w-full text-sm hover:text-blue-500 hover:opacity-100"
          checked={transitionsEnabled}
          title="Disable to improve performance when zooming"
          onChange={(e) => setTransitionsEnabled(e.target.checked)}
        >
          <Icon className="ml-1.5" path={mdiTransition} size="1.25em" />
          <span className="flex-1">Transitions</span>
        </CheckboxWithLabel>
        <CheckboxWithLabel
          className="group w-full text-sm hover:text-blue-500 hover:opacity-100"
          checked={labelsVisible}
          title="Disable to improve performance"
          onChange={(e) => setLabelsVisible(e.target.checked)}
        >
          <Icon className="ml-1.5" path={mdiLabel} size="1.25em" />
          <span className="flex-1">Labels</span>
        </CheckboxWithLabel>
        <CheckboxWithLabel
          className="group w-full text-sm hover:text-blue-500 hover:opacity-100"
          checked={showFilesWithoutChanges}
          title="Show files that have had no changes in the selected time range"
          onChange={(e) => setShowFilesWithoutChanges(e.target.checked)}
        >
          <Icon className="ml-1.5" path={mdiClockEdit} size="1.25em" />
          <span className="flex-1">Show files with no activity</span>
        </CheckboxWithLabel>
        <CheckboxWithLabel
          className="group w-full text-sm hover:text-blue-500 hover:opacity-100"
          checked={hierarchyType === "FLAT"}
          title="Show all files on the same level, instead of as a file tree"
          onChange={() => {
            if (hierarchyType === "FLAT") setHierarchyType("NESTED")
            else setHierarchyType("FLAT")
          }}
        >
          <Icon className="ml-1.5" path={mdiFileTree} size="1.25em" />
          <span className="flex-1">Flatten file tree</span>
        </CheckboxWithLabel>
        {/* <CheckboxWithLabel
        className="text-sm"
        checked={theme === "DARK"}
        onChange={() => {
          if (theme === "DARK") setTheme("LIGHT")
          else setTheme("DARK")
        }}
        title="Use a dark theme instead of light"
      >
        <Icon className="ml-1.5" path={mdiThemeLightDark} size="1.25em" />
        Use dark theme
      </CheckboxWithLabel> */}
        <CheckboxWithLabel
          className="group w-full text-sm hover:text-blue-500 hover:opacity-100"
          checked={showOnlySearchMatches}
          title="When searching, hide files that do not match the search query"
          onChange={(e) => setShowOnlySearchMatches(e.target.checked)}
        >
          <Icon className="ml-1.5" path={mdiFilter} size="1.25em" />
          Show only search matches
        </CheckboxWithLabel>
        <RenderCutOff />
        <ClearCacheForm />
      </div>
    </Modal>
  )
}

function RenderCutOff() {
  const { renderCutOff, setRenderCutOff } = useOptions()
  const [value, setValue] = useState(renderCutOff)
  const [, startTransition] = useTransition()
  return (
    <label
      className="label group flex w-full items-center justify-start gap-2 text-sm hover:text-blue-500 hover:opacity-100"
      title="Increase to improve render performance, decrease it to get higher level of detail"
    >
      <span className="group flex grow items-center gap-2">
        <Icon className="ml-1.5" path={mdiContentCut} size="1.25em" />
        Pixel render cut-off
      </span>
      <input
        type="number"
        min={0}
        value={value}
        className="mr-1 w-12 place-self-end border-b-2"
        onChange={(x) => {
          const v = Number.isNaN(x.target.valueAsNumber)
            ? getDefaultOptionsContextValue().renderCutOff
            : x.target.valueAsNumber
          setValue(v)
          startTransition(() => setRenderCutOff(v))
        }}
      />
    </label>
  )
}

import { mdiEyeOff, mdiDelete, mdiDeleteEmpty } from "@mdi/js"
import { useData } from "~/contexts/DataContext"
import { Icon } from "~/components/Icon"
import { Code } from "~/components/util"
import { useEffect, useMemo, useRef, useState } from "react"
import { getSep } from "~/shared/util"
import { useViewSubmit } from "~/hooks"
import { cn } from "~/styling"
import { Modal } from "~/components/modals/Modal"

export function HideFilesModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const { databaseInfo } = useData()

  return (
    <HideFilesModalContent
      key={open.toString()}
      open={open}
      initialHiddenFiles={databaseInfo.hiddenFiles}
      onClose={onClose}
    />
  )
}

function HideFilesModalContent({
  open,
  initialHiddenFiles,
  onClose
}: {
  open: boolean
  initialHiddenFiles: string[]
  onClose: () => void
}) {
  const inputRef = useRef<HTMLInputElement>(null)
  const submit = useViewSubmit()
  const [hiddenFiles, setHiddenFiles] = useState(initialHiddenFiles)

  const hasChanges = useMemo(
    () => JSON.stringify(initialHiddenFiles) !== JSON.stringify(hiddenFiles),
    [initialHiddenFiles, hiddenFiles]
  )

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  return (
    <Modal
      open={open}
      title="Hide files"
      icon={mdiEyeOff}
      onClose={() => {
        if (hasChanges) {
          const formData = new FormData()
          formData.append("replaceHiddenFiles", "true")
          for (const hidden of hiddenFiles) {
            formData.append("hidePath", hidden)
          }
          submit(formData, { method: "post" })
        }
        onClose()
      }}
    >
      <div className="flex min-h-0 max-w-[40ch] flex-col items-start justify-center gap-3 overflow-y-auto p-2 pl-0">
        <p className="text-sm">
          Pattern-matched files are hidden from the file tree and excluded from metric computations.
        </p>
        <p className="text-sm">
          Hidden files behave like entries in a <Code inline>.gitignore</Code> file.
        </p>
        <form
          method="post"
          className="flex w-full flex-wrap items-end gap-2"
          onSubmit={(evt) => {
            evt.preventDefault()
            const hidePath = new FormData(evt.currentTarget).get("hide")

            if (typeof hidePath !== "string" || hidePath.length === 0) {
              return
            }

            setHiddenFiles((prev) => (prev.includes(hidePath) ? prev : [hidePath, ...prev]))

            evt.currentTarget.reset()
            inputRef.current?.setCustomValidity("")
          }}
        >
          <label className="label flex min-w-0 flex-1 flex-col gap-2">
            Path or glob
            <input
              ref={inputRef}
              required
              type="text"
              className="input"
              name="hide"
              placeholder="Enter pattern..."
              onChange={(e) => {
                // Update form validity based on whether pattern already exists
                const exists = hiddenFiles.includes(e.target.value)
                e.target.setCustomValidity(exists ? "Pattern already exists" : "")
              }}
            />
          </label>
          <button className="btn btn--primary whitespace-nowrap">Hide</button>
        </form>
        <div className="flex w-full items-center justify-between">
          <h3 className="text-tertiary-text dark:text-tertiary-text-dark text-sm font-bold tracking-wide uppercase">
            Hidden files/patterns
          </h3>
          <button
            type="button"
            className={cn("btn btn--danger btn--text", {
              hidden: hiddenFiles.length === 0
            })}
            onClick={() => {
              setHiddenFiles([])
            }}
          >
            Reset
          </button>
        </div>
        <div className="flex max-h-96 min-h-0 w-full flex-col gap-2 overflow-y-auto">
          {hiddenFiles.length > 0 ? (
            hiddenFiles.map((hidden) => {
              return (
                <div
                  key={hidden}
                  className="secondary grid grid-cols-[1fr_auto] items-center gap-x-2 gap-y-0 rounded-md px-2 py-1 text-sm"
                  title={hidden}
                >
                  <span className="truncate text-sm" title={hidden}>
                    {hiddenFileFormat(hidden)}
                  </span>
                  <button
                    className="btn btn--text btn--hover-swap h-6"
                    title={`Unhide ${hidden}`}
                    onClick={() => {
                      setHiddenFiles((prev) => prev.filter((f) => f !== hidden))
                    }}
                  >
                    <Icon path={mdiDelete} className="inline-block h-full" />
                    <Icon path={mdiDeleteEmpty} className="hover-swap inline-block h-full" />
                  </button>
                </div>
              )
            })
          ) : (
            <div className="text-secondary-text dark:text-secondary-text-dark text-sm opacity-70">No hidden files</div>
          )}
        </div>
      </div>
    </Modal>
  )
}

function hiddenFileFormat(ignored: string) {
  if (!ignored.includes(getSep(ignored))) return ignored
  const split = ignored.split(getSep(ignored))
  return split[split.length - 1]
}

