import { useMemo, useRef, useState, useTransition, useId, createRef, useEffect, useCallback } from "react"
import type { SearchResults } from "~/contexts/SearchContext"
import { useSearch } from "~/contexts/SearchContext"

import type { GitObject, GitTreeObject } from "~/shared/model"
import { useData } from "~/contexts/DataContext"
import { useClickedObjectIsZoomPath, useSetClickedObjectPath } from "~/state/stores/clicked-object"
import { getSeparator } from "~/shared/util"
import { Icon } from "~/components/Icon"
import { mdiFolder, mdiFileOutline, mdiMagnify, mdiClose, mdiFile } from "@mdi/js"
import { useMetrics } from "~/contexts/MetricContext"
import { useOptions } from "~/contexts/OptionsContext"
import { useKey } from "~/hooks"
import { useQueryState } from "nuqs"
import { flushSync } from "react-dom"

function findSearchResults(tree: GitTreeObject, searchString: string): SearchResults {
  const searchResults: Record<string, GitObject> = {}
  function subTreeSearch(subTree: GitTreeObject) {
    for (const child of subTree.children) {
      if (child.path.toLowerCase().includes(searchString.toLowerCase()) && searchString) {
        searchResults[child.path] = child
      }
      if (child.type === "tree") subTreeSearch(child)
    }
  }
  subTreeSearch(tree)
  return searchResults
}

export function SearchCard() {
  const searchRootRef = useRef<HTMLFormElement>(null)
  const searchFieldRef = useRef<HTMLInputElement>(null)
  const [zoomPath] = useQueryState("zoomPath")
  const [isTransitioning, startTransition] = useTransition()
  const [searchText, setSearchText] = useState("")
  const clickedObjectIsZoomPath = useClickedObjectIsZoomPath()
  const setClickedObject = useSetClickedObjectPath()
  const { searchResults, setSearchResults } = useSearch()
  const searchResultsArray = useMemo(() => Object.values(searchResults), [searchResults])
  const id = useId()
  const { databaseInfo } = useData()

  useEffect(() => {
    setSearchResults(searchText.length > 0 ? findSearchResults(databaseInfo.fileTree, searchText) : {})
  }, [searchText, setSearchResults, databaseInfo.fileTree])

  const options = useOptions()
  const [metrics] = useMetrics()

  const resultRefs = Object.keys(searchResults).map(() => createRef<HTMLButtonElement>())

  const closeSearch = useCallback(() => {
    setSearchText("")
    setSearchResults({})
  }, [setSearchResults])

  useEffect(() => {
    startTransition(() => {
      if (searchText.trim() === "") {
        setSearchResults({})
      } else {
        setSearchResults(findSearchResults(databaseInfo.fileTree, searchText))
      }
    })
  }, [searchText, databaseInfo.fileTree, setSearchResults])

  useKey({ key: "f", ctrlOrMeta: true }, (event) => {
    event.preventDefault()
    searchFieldRef.current?.focus()
  })

  useEffect(() => {
    function handlePointerDown(event: PointerEvent) {
      if (event.target instanceof Node && !searchRootRef.current?.contains(event.target)) {
        closeSearch()
      }
    }

    document.addEventListener("pointerdown", handlePointerDown)
    return () => document.removeEventListener("pointerdown", handlePointerDown)
  }, [closeSearch])

  function focusResultAtIndex(nextIndex: number) {
    resultRefs[nextIndex].current?.focus()
  }

  const items = Object.values(searchResults)
  const zoomedFolderName = zoomPath ? zoomPath.split(getSeparator(zoomPath)).at(-1) : databaseInfo.repo
  const helpText = `Search within ${zoomedFolderName}`
  return (
    <form
      ref={searchRootRef}
      className="not-focus-within:has-placeholder-shown:w-button pointer-events-none absolute top-[calc(2*var(--spacing)+2px)] right-4 z-10 flex w-[calc(var(--spacing-sidepanel)-4*var(--spacing))] flex-col gap-2 transition-[left,width,translate] duration-75 **:pointer-events-auto not-focus-within:has-placeholder-shown:static not-focus-within:has-placeholder-shown:translate-x-0"
      onSubmit={(event) => {
        event.preventDefault()
        closeSearch()
        event.currentTarget.querySelector("input")?.blur()
      }}
      onBlur={(event) => {
        if (event.relatedTarget instanceof Node && event.currentTarget.contains(event.relatedTarget)) {
          return
        }
        closeSearch()
      }}
    >
      <button className="hidden min-w-max cursor-pointer peer-placeholder-shown:hidden peer-focus:inline">
        <Icon path={mdiClose} size="1em" />
      </button>
      <label
        className="focus-within:input min-h-button h-button max-h-button relative flex w-full min-w-0 cursor-pointer flex-row-reverse items-center gap-2 overflow-hidden not-focus-within:has-placeholder-shown:grow-0 not-focus-within:has-placeholder-shown:gap-0"
        title={helpText}
      >
        <input
          ref={searchFieldRef}
          className="peer w-full grow placeholder-shown:not-focus:w-0 placeholder-shown:not-focus:min-w-0"
          id={id}
          type="search"
          placeholder={helpText}
          value={searchText}
          onKeyDown={(event) => {
            if (event.key === "Enter") {
              event.preventDefault()
            }
            if (event.key === "Escape") {
              event.preventDefault()
              closeSearch()
              event.currentTarget.blur()
            }
            if (event.key === "ArrowDown") {
              event.preventDefault()
              if (resultRefs.length > 0) {
                focusResultAtIndex(0)
              }
            }
          }}
          onFocus={() => {
            if (!clickedObjectIsZoomPath) {
              setClickedObject(null)
            }
          }}
          onChange={(event) => {
            setSearchText(event.target.value)
          }}
        />
        <Icon path={mdiMagnify} className="hidden min-w-max peer-placeholder-shown:inline peer-focus:hidden" />
        <span className="sr-only">Search</span>
        {isTransitioning || searchText.length > 0 ? (
          <p className="text-secondary-text dark:text-secondary-text-dark absolute right-8 ml-2 text-sm select-none">
            {isTransitioning ? "Searching..." : searchText.length > 0 ? `${searchResultsArray.length} results` : null}
          </p>
        ) : null}
      </label>
      {searchResultsArray.length > 0 ? (
        <div className="card bg-tertiary-bg/10 dark:bg-tertiary-bg-dark/50 w-sidepanel max-h-sidepanel relative min-h-0 overflow-auto backdrop-blur-lg">
          {items.map((object, i) => (
            <button
              ref={resultRefs[i]}
              key={object.path}
              className="flex cursor-pointer items-center justify-start gap-2 text-sm font-bold"
              title={object.path}
              type="reset"
              value={object.path}
              onKeyDown={(event) => {
                const currentIndex = resultRefs.findIndex((ref) => ref.current === event.currentTarget)

                if (event.key === "Escape") {
                  searchFieldRef.current?.focus()
                  searchFieldRef.current?.select()
                }

                if (event.key === "ArrowDown") {
                  event.preventDefault()
                  if (resultRefs.length === 0) return
                  const nextIndex = (currentIndex + 1) % resultRefs.length
                  focusResultAtIndex(nextIndex)
                }
                if (event.key === "ArrowUp") {
                  event.preventDefault()
                  if (resultRefs.length === 0) return
                  const prevIndex = currentIndex - 1
                  if (prevIndex < 0) {
                    searchFieldRef.current?.focus()
                    searchFieldRef.current?.select()
                    return
                  }
                  focusResultAtIndex(prevIndex)
                }
              }}
              onClick={() => {
                flushSync(() => {
                  setClickedObject(object.path)
                  setSearchResults({})
                  setSearchText("")
                })
              }}
            >
              {object.type === "tree" ? (
                <Icon path={object.type === "tree" ? mdiFolder : mdiFileOutline} size={0.75} className="shrink-0" />
              ) : (
                <Icon
                  color={metrics.get(options.metricType)?.categoriesMap.get(object.path)?.[0]?.color ?? "grey"}
                  path={mdiFile}
                  size={0.75}
                  className="shrink-0"
                />
              )}
              <span className="text-secondary-text dark:hover:text-primary-text-dark hover:text-primary-text dark:text-secondary-text-dark truncate">
                {object.path.split(getSeparator(object.path)).slice(1).join("/") ?? object.path}
              </span>
            </button>
          ))}
        </div>
      ) : null}
    </form>
  )
}

import { useMemo, useTransition, useState } from "react"
import { useData } from "~/contexts/DataContext"
import type { ContributorGroup, Person } from "~/shared/model"
import { CheckboxWithLabel } from "~/components/modals/utils/CheckboxWithLabel"
import { useMetrics } from "~/contexts/MetricContext"
import { Icon } from "~/components/Icon"
import {
  mdiAccountMultiplePlus,
  mdiAccountMultipleMinus,
  mdiAccountMultipleRemove,
  mdiAccountRemove,
  mdiAccountMultipleCheck,
  mdiAccountMultiple
} from "@mdi/js"
import { LegendDot } from "~/components/util"
import { useViewSubmit } from "~/hooks"
import { Modal } from "~/components/modals/Modal"
import { cn } from "~/styling"
import { autoBuildContributorGroups } from "~/components/modals/utils/autoBuildContributorGroups"
import { pickContributorGroupDisplayName } from "~/components/modals/utils/displayNameStrategy"

//Wrapper to inject necessary data and reset internal state when reopening the modal
export function GroupContributorsModal({ open, onClose }: { open: boolean; onClose: () => void }) {
  const { databaseInfo } = useData()
  const [, contributorColors] = useMetrics()
  const { contributorGroups, contributors } = databaseInfo

  return (
    <GroupContributorsModalContent
      key={open.toString()} // Reset internal state when reopening the modal
      open={open}
      contributorGroups={contributorGroups}
      contributors={contributors}
      contributorColors={contributorColors}
      onClose={onClose}
    />
  )
}

function GroupContributorsModalContent({
  open,
  contributorGroups,
  contributors,
  contributorColors,
  onClose
}: {
  open: boolean
  contributorGroups: ContributorGroup[]
  contributors: Person[]
  contributorColors: Map<string, string>
  onClose: () => void
}) {
  const [selectedContributors, setSelectedContributors] = useState<Person[]>([])
  const [localContributorGroups, setLocalContributorGroups] = useState<ContributorGroup[]>(contributorGroups)
  const [filter, setFilter] = useState("")
  const [, startTransition] = useTransition()
  const submit = useViewSubmit()

  // When the modal is closed, check if the contributor groups have changed. If they have, submit the new groups as custom close action.
  const handleCloseWithSubmitIfChanged = () => {
    const currentSerialized = JSON.stringify(localContributorGroups)
    const originalSerialized = JSON.stringify(contributorGroups)
    if (currentSerialized === originalSerialized) return
    const form = new FormData()
    form.append("groupedContributors", currentSerialized)
    submit(form, {
      method: "post"
    })
  }

  function makePrimaryAlias(aliasName: string, groupIndex: number) {
    setLocalContributorGroups((prev) => {
      const group = prev[groupIndex]
      if (!group || group.displayName === aliasName) return prev
      return prev.map((group, i) => (i === groupIndex ? { ...group, displayName: aliasName } : group))
    })
  }

  const groupedContributorsSet = useMemo(
    () => new Set(localContributorGroups.flatMap((group) => group.members).map(uniqueId)),
    [localContributorGroups]
  )

  const ungroupedContributorsSorted = useMemo(
    () =>
      contributors
        .filter((contributor) => !groupedContributorsSet.has(uniqueId(contributor)))
        .toSorted((a, b) => a.name.localeCompare(b.name)),
    [contributors, groupedContributorsSet]
  )

  const ungroupedContributorsFiltered = useMemo(() => {
    return ungroupedContributorsSorted.filter((contributor) =>
      contributor.name.toLowerCase().includes(filter.toLowerCase())
    )
  }, [ungroupedContributorsSorted, filter])

  const autoGroupCandidates = useMemo(
    () => autoBuildContributorGroups(ungroupedContributorsSorted),
    [ungroupedContributorsSorted]
  )
  const autoGroupAuthorCount = useMemo(
    () => autoGroupCandidates.reduce((sum, group) => sum + group.members.length, 0),
    [autoGroupCandidates]
  )
  const selectedIds = useMemo(() => new Set(selectedContributors.map(uniqueId)), [selectedContributors])
  const isAllVisibleSelected =
    ungroupedContributorsFiltered.length > 0 &&
    ungroupedContributorsFiltered.every((contributor) => selectedIds.has(uniqueId(contributor)))

  const getColorFromDisplayName = (displayName: string) => contributorColors.get(displayName) ?? "#333"

  const ungroupedContributorsEntries = ungroupedContributorsFiltered.map((contributor) => {
    const isContributorSelected = selectedContributors.some((selected) => uniqueId(selected) === uniqueId(contributor))
    return (
      <CheckboxWithLabel
        key={uniqueId(contributor) + isContributorSelected}
        className="contents"
        checkBoxClassName="ml-auto"
        checked={isContributorSelected}
        onChange={(e) => {
          setSelectedContributors((prev) => {
            if (e.target?.checked) return [...prev, contributor]
            else return prev.filter((selected) => uniqueId(selected) !== uniqueId(contributor))
          })
        }}
      >
        <div className="contents">
          <LegendDot dotColor={getColorFromDisplayName(contributor.name)} />
          <span className="truncate font-bold" title={contributor.name}>
            {contributor.name}
          </span>
          <p
            className="text-secondary-text dark:text-secondary-text-dark truncate text-xs leading-tight"
            title={contributor.email}
          >
            {contributor.email}
          </p>
        </div>
      </CheckboxWithLabel>
    )
  })

  const groupedContributorsEntries = localContributorGroups.map(({ displayName, members }, aliasGroupIndex) => {
    const color = getColorFromDisplayName(displayName)

    return (
      <div
        key={aliasGroupIndex}
        className="card bg-primary-bg dark:bg-primary-bg-dark group m-0 flex h-full flex-col justify-between p-2"
        title={displayName}
      >
        <div className="flex w-full flex-col gap-2">
          <div className="flex w-full justify-between gap-0">
            <div className="bg-primary-bg dark:bg-primary-bg-dark hover:bg-secondary-bg focus-within:bg-secondary-bg focus-within:dark:bg-secondary-bg-dark hover:dark:bg-secondary-bg-dark focus-within:ring-blue-primary flex items-center gap-1 rounded-md px-2 py-1 transition-colors focus-within:ring-2">
              <LegendDot dotColor={color} />
              <select
                className="input h-fit w-full truncate border-0 bg-transparent px-0 text-sm font-bold ring-0!"
                value={displayName}
                onChange={(e) => makePrimaryAlias(e.target.value, aliasGroupIndex)}
              >
                {Array.from(new Set([displayName, ...members.map((member) => member.name)])).map((name) => (
                  <option key={name} value={name}>
                    {name}
                  </option>
                ))}
              </select>
            </div>
            <button
              className="btn btn--text hover:btn--danger transition-colors"
              title="Ungroup"
              aria-label="Ungroup"
              onClick={() => setLocalContributorGroups((prev) => prev.filter((_, i) => i !== aliasGroupIndex))}
            >
              <Icon path={mdiAccountMultipleRemove} size={1} />
            </button>
          </div>
          <ul className="list-disc pl-6">
            {members
              .filter((value, index, array) => array.map((v) => v.email).indexOf(value.email) === index)
              .map((contributor) => (
                <AliasEntry
                  key={uniqueId(contributor)}
                  contributor={contributor}
                  onClick={() =>
                    setLocalContributorGroups((prev) =>
                      prev.flatMap((group, i) => {
                        if (i !== aliasGroupIndex) return [group]
                        const remainingMembers = group.members.filter((member) => member.email !== contributor.email)
                        return remainingMembers.length > 0 ? [{ ...group, members: remainingMembers }] : []
                      })
                    )
                  }
                />
              ))}
          </ul>
        </div>
        <div
          className={cn(
            "relative flex h-full w-full origin-top items-end justify-end transition-all delay-50 duration-100",
            selectedContributors.length === 0 ? "max-h-0 scale-y-0 opacity-0" : "max-h-10 scale-y-100 opacity-100"
          )}
        >
          <button
            className="btn btn--primary right bottom absolute h-fit w-fit px-2 py-1 text-xs shadow-lg"
            title="Add selected contributors to this group"
            disabled={selectedContributors.length === 0}
            onClick={() => {
              setLocalContributorGroups((prev) => {
                return prev.map((group, i) =>
                  i === aliasGroupIndex ? { ...group, members: group.members.concat(selectedContributors) } : group
                )
              })
              setSelectedContributors([])
            }}
          >
            <Icon path={mdiAccountMultiplePlus} size={0.75} />
            Add contributor
          </button>
        </div>
      </div>
    )
  })

  return (
    <Modal
      open={open}
      title="Group contributors"
      icon={mdiAccountMultiple}
      onClose={() => {
        handleCloseWithSubmitIfChanged()
        onClose()
      }}
    >
      <div className="flex min-h-0 w-auto max-w-(--breakpoint-lg) min-w-0 flex-col gap-2 p-4">
        <div className="grid grid-cols-[1fr_1fr] gap-2">
          <h3 className="text-center text-lg font-bold">
            Ungrouped Contributors ({ungroupedContributorsSorted.length})
          </h3>
          <h3 className="text-center text-lg font-bold">Contributor Groups ({groupedContributorsEntries.length})</h3>
        </div>
        <div className="grid min-h-0 flex-1 grid-cols-[1fr_1fr] gap-2">
          <div className="flex min-h-0 flex-col rounded-md">
            <div className="flex gap-2 p-2">
              <input
                className="input min-w-0"
                type="search"
                placeholder="Filter..."
                disabled={ungroupedContributorsSorted.length === 0}
                onChange={(e) => startTransition(() => setFilter(e.target.value))}
              />
              <button
                disabled={selectedContributors.length === 0}
                className="btn w-max grow"
                title="Clear selection"
                onClick={() => setSelectedContributors([])}
              >
                Clear
              </button>
              <button
                disabled={ungroupedContributorsFiltered.length === 0}
                className="btn w-max grow"
                title={isAllVisibleSelected ? "Deselect selected contributors" : "Select all contributors from list"}
                onClick={() =>
                  setSelectedContributors((selected) =>
                    isAllVisibleSelected
                      ? selected.filter(
                          (contributor) =>
                            !ungroupedContributorsFiltered.some(
                              (visibleContributor) => uniqueId(visibleContributor) === uniqueId(contributor)
                            )
                        )
                      : [
                          ...selected,
                          ...ungroupedContributorsFiltered.filter(
                            (contributor) =>
                              !selected.some(
                                (selectedContributor) => uniqueId(selectedContributor) === uniqueId(contributor)
                              )
                          )
                        ]
                  )
                }
              >
                {isAllVisibleSelected ? "Deselect all" : "Select all"}
              </button>
            </div>
            <div className="bg-primary-bg dark:bg-primary-bg-dark grid min-h-0 w-full grid-cols-[min-content_3fr_3fr_min-content] items-center gap-x-4 gap-y-1 overflow-y-auto rounded-lg p-2">
              {ungroupedContributorsFiltered.length > 0 ? (
                ungroupedContributorsEntries
              ) : (
                <p className="col-span-full place-self-center text-sm">
                  {filter.length > 0 ? "No contributors found" : "All contributors have been grouped"}
                </p>
              )}
            </div>
          </div>
          <div className="min-h-0 overflow-y-auto">
            <div className="grid h-min min-h-0 grid-cols-1 gap-4 rounded-md p-2 lg:grid-cols-1 xl:grid-cols-2">
              {localContributorGroups.length > 0 ? (
                groupedContributorsEntries
              ) : (
                <p className="col-span-2 text-center text-sm">No contributors have been grouped yet</p>
              )}
            </div>
          </div>
        </div>
        <div className="grid grid-cols-[1fr_1fr] gap-2">
          <div className="flex w-full flex-row justify-end gap-2">
            {autoGroupAuthorCount > 0 ? (
              <button
                className="btn btn--primary w-fit transition-all duration-100"
                title={
                  autoGroupCandidates.length === 0
                    ? "No ungrouped contributors share the same name or email"
                    : `Create ${autoGroupCandidates.length} inferred group${autoGroupCandidates.length > 1 ? "s" : ""} containing ${autoGroupAuthorCount} author${autoGroupAuthorCount > 1 ? "s" : ""}`
                }
                disabled={autoGroupCandidates.length === 0}
                onClick={() => {
                  setLocalContributorGroups((prev) => {
                    const next = prev.slice()
                    for (const autoGroup of autoGroupCandidates) next.push(autoGroup)
                    return next
                  })
                  setSelectedContributors([])
                }}
              >
                <Icon path={mdiAccountMultipleCheck} size={1} />
                Auto group ({autoGroupAuthorCount})
              </button>
            ) : null}
            <button
              className="btn btn--primary w-fit transition-all duration-100"
              title={
                selectedContributors.length < 2
                  ? "Select at least 2 contributors to group them"
                  : "Group the selected contributors"
              }
              disabled={selectedContributors.length < 2}
              onClick={() => {
                setLocalContributorGroups((prev) => [
                  ...prev,
                  { displayName: pickContributorGroupDisplayName(selectedContributors), members: selectedContributors }
                ])
                setSelectedContributors([])
              }}
            >
              <Icon path={mdiAccountMultiplePlus} size={1} />
              Create new group
            </button>
          </div>
          <div className="flex w-full flex-row justify-end gap-2">
            <button
              className="btn btn--danger w-fit transition-all duration-100"
              disabled={localContributorGroups.length === 0}
              onClick={() => {
                if (confirm("Are you sure you want to ungroup all grouped contributors?")) setLocalContributorGroups([])
              }}
            >
              <Icon path={mdiAccountMultipleMinus} size={1} />
              Ungroup all
            </button>
          </div>
        </div>
      </div>
    </Modal>
  )
}

function AliasEntry({
  contributor,
  onClick,
  disabled
}: {
  contributor: Person
  disabled?: boolean
  onClick: () => void
}) {
  return (
    <li className="list-item w-full items-center gap-2">
      <button
        className="group/alias grid w-full cursor-pointer grid-cols-[minmax(0,1fr)_1rem] items-center gap-1 text-start hover:text-red-500"
        disabled={disabled}
        title={"Remove " + contributor.email}
        aria-label={"Remove " + contributor.email}
        onClick={onClick}
      >
        <span className="label truncate text-xs">{contributor.email}</span>
        <div className="flex opacity-0 transition-opacity duration-200 group-hover/alias:opacity-100">
          <Icon path={mdiAccountRemove} size={0.75} />
        </div>
      </button>
