import { useQueryStates } from "nuqs"
import { useFetcher, href } from "react-router"
import { commitsSerializer, type loader } from "~/routes/api.commits"
import { viewSearchParamsConfig } from "~/shared/viewParams"
import { useClickedObjectPath } from "~/state/stores/clicked-object"
import { COMMIT_STEP, CommitHistory } from "~/components/inspection/CommitHistory"
import { useCallback, useEffect, useMemo, useState } from "react"
import { CollapsibleHeader } from "~/components/CollapsibleHeader"
import { useSelectedCategories } from "~/state/stores/selection"
import { useOptions } from "~/contexts/OptionsContext"
import { ClickedObjectButton } from "~/components/buttons/ClickedObjectButton"
import { useData } from "~/contexts/DataContext"

export function CommitsInspection({ className = "" }: { className?: string }) {
  const [open, setOpen] = useState(true)
  const clickedObjectPath = useClickedObjectPath()
  const { load, data, state, reset } = useFetcher<typeof loader>()
  const [{ path, branch, start, end }] = useQueryStates(viewSearchParamsConfig)
  const { databaseInfo } = useData()
  const [rangeStart, rangeEnd] = databaseInfo.timerange
  const resolvedStart = start ?? rangeStart
  const resolvedEnd = end ?? rangeEnd

  const { metricType } = useOptions()
  const selectedCategories = useSelectedCategories()

  // Memoize selected authors to prevent unnecessary re-renders
  const selectedContributors = useMemo(
    () => (metricType === "TOP_CONTRIBUTOR" || metricType === "CONTRIBUTORS" ? selectedCategories : []),
    [metricType, selectedCategories]
  )

  // Memoize loadCommits to use in callbacks and pagination
  const loadCommits = useCallback(
    ({ objectPath, contributors, count }: { objectPath: string; contributors: string[]; count: number }) => {
      const url =
        href("/api/commits") +
        commitsSerializer({
          objectPath,
          path,
          branch,
          count,
          contributors,
          start: resolvedStart,
          end: resolvedEnd
        })

      if (open) {
        load(url)
      }
    },
    [branch, load, open, path, resolvedEnd, resolvedStart]
  )

  // Reload commits when clicked object or selected authors change
  useEffect(() => {
    const pathToLoad = clickedObjectPath

    loadCommits({ objectPath: pathToLoad, contributors: selectedContributors, count: COMMIT_STEP })
    return () => reset()
  }, [clickedObjectPath, loadCommits, reset, selectedContributors])

  return (
    <CollapsibleHeader
      className={className}
      title={() => (
        <>
          Commits
          <ClickedObjectButton />
        </>
      )}
      contentClassName="flex flex-col gap-2"
      open={open}
      onToggle={(open) => {
        setOpen(open)
        if (open) {
          if (state === "idle") {
            loadCommits({ objectPath: clickedObjectPath, contributors: selectedContributors, count: COMMIT_STEP })
          }
        } else {
          reset()
        }
      }}
    >
      <CommitHistory
        commits={data?.commits ?? []}
        loadedCommitCount={data?.currentCommitCount ?? COMMIT_STEP}
        totalCommitCount={data?.totalCommitCount ?? 0}
        isLoading={state !== "idle"}
        onShowMoreCommits={() => {
          loadCommits({
            objectPath: clickedObjectPath,
            contributors: selectedContributors,
            count: (data?.currentCommitCount ?? COMMIT_STEP) + COMMIT_STEP
          })
        }}
      />
    </CollapsibleHeader>
  )
}

import { mdiOpenInNew, mdiEyeOffOutline } from "@mdi/js"
import { useQueryState } from "nuqs"
import { useNavigation, Form } from "react-router"
import { ZoomButtons } from "~/components/buttons/ZoomButtons"
import { Icon } from "~/components/Icon"
import { useViewAction } from "~/hooks"
import { isRepositoryRoot, last, resolveParentFolder } from "~/shared/util"
import { viewSearchParamsConfig } from "~/shared/viewParams"
import { useClickedObject, useSetClickedObjectPath } from "~/state/stores/clicked-object"

export function InteractionButtons() {
  const clickedObject = useClickedObject()
  const setClickedObjectPath = useSetClickedObjectPath()
  const viewAction = useViewAction()
  const { state } = useNavigation()
  const [, setZoomPath] = useQueryState("zoomPath", viewSearchParamsConfig.zoomPath)

  if (!clickedObject) {
    return null
  }

  const isRoot = isRepositoryRoot(clickedObject)
  const isBlob = clickedObject.type === "blob"
  const extension = last(clickedObject.name.split("."))

  return (
    <div className="flex flex-wrap">
      <Form method="post" action={viewAction}>
        <input type="hidden" name="open" value={clickedObject.path} />
        <button
          className="btn btn--text"
          disabled={state !== "idle"}
          title={
            clickedObject.type === "blob"
              ? `Open ${clickedObject.name} in default app`
              : `Browse ${clickedObject.name} in system explorer`
          }
        >
          <Icon path={mdiOpenInNew} size="1.25em" className="w-max" />
          {clickedObject.type === "blob" ? "Open" : "Browse"}
        </button>
      </Form>
      <Form
        className="w-max"
        method="post"
        action={viewAction}
        onSubmit={() => {
          if (!isBlob) setZoomPath(resolveParentFolder(clickedObject.path))
          setClickedObjectPath(null)
        }}
      >
        <input type="hidden" name="hide" value={clickedObject.path} />
        {!isRoot && isBlob ? (
          <button
            className="btn btn--text"
            disabled={state !== "idle"}
            title={`Hide ${clickedObject.name} from visualization`}
          >
            <Icon path={mdiEyeOffOutline} />
            Hide
          </button>
        ) : null}
      </Form>
      {isBlob ? (
        <>
          {clickedObject.name.includes(".") ? (
            <Form className="w-max" method="post" action={viewAction}>
              <input type="hidden" name="hide" value={`*.${extension}`} />
              <button
                className="btn btn--text"
                disabled={state !== "idle"}
                title={`Hide all files with .${extension} extension`}
              >
                <Icon path={mdiEyeOffOutline} />
                <span>Hide *.{extension}</span>
              </button>
            </Form>
          ) : null}
        </>
      ) : null}
      <ZoomButtons />
    </div>
  )
}

import { mdiFileOutline, mdiFolderOutline, mdiSourceRepository } from "@mdi/js"
import byteSize from "byte-size"
import { useEffect, useState, type CSSProperties, type ReactNode } from "react"
import { href, useFetcher } from "react-router"
import { Icon } from "~/components/Icon"
import { missingInMapColor, UNKNOWN_CATEGORY } from "~/const"
import { useOptions } from "~/contexts/OptionsContext"
import { dateFormatRelative, isTree, last } from "~/shared/util"
import { useClickedObject, useClickedObjectPath, useBlobColor } from "~/state/stores/clicked-object"
import { cn } from "~/styling"
import { usePathIsRepositoryRoot } from "~/hooks"
import { FileSizeMetric } from "~/metrics/fileSize"
import { ContributorsMetric } from "~/metrics/contributors"
import type { MetricType } from "~/metrics/metrics"
import { CommitsMetric } from "~/metrics/mostCommits"
import { TopContributorMetric } from "~/metrics/topContributer"
import { LinesChangedMetric } from "~/metrics/linesChanged"
import { LastChangedMetric } from "~/metrics/lastChanged"
import { GroupContributorsModal } from "~/components/modals/GroupContributorsModal"
import { useQueryStates } from "nuqs"
import { viewSearchParamsConfig, viewSerializer } from "~/shared/viewParams"
import type { ClickedObjectInfo, HexColor } from "~/shared/model"
import type { loader } from "~/routes/api.metrics"
import { useData } from "~/contexts/DataContext"

export function MetricsInspection() {
  const clickedObject = useClickedObject()
  const { databaseInfo } = useData()
  const { metricType, setMetricType } = useOptions()
  const [modalOpen, setModalOpen] = useState(false)

  const isBlob = clickedObject?.type === "blob"

  const { data, load, reset } = useFetcher<typeof loader>()

  const objectColor = useBlobColor(clickedObject) ?? missingInMapColor

  const clickedObjectPath = useClickedObjectPath()
  const isRepo = usePathIsRepositoryRoot(clickedObjectPath)
  const [params] = useQueryStates(viewSearchParamsConfig)
  const [rangeStart, rangeEnd] = databaseInfo.timerange

  useEffect(() => {
    load(
      href("/api/metrics") +
        viewSerializer({
          ...params,
          objectPath: clickedObjectPath,
          start: params.start ?? rangeStart,
          end: params.end ?? rangeEnd
        })
    )
    return () => reset()
  }, [clickedObjectPath, load, params, rangeEnd, rangeStart, reset])

  const currentFetcherData = data

  const selectedRangeMetricsLoaded = isBlob || currentFetcherData !== undefined

  const contributions = isBlob
    ? (databaseInfo.contribSumPerFile[clickedObject.path] ?? 0)
    : currentFetcherData?.contributions

  const commitCount = isBlob
    ? (databaseInfo.commitCounts[clickedObject.path] ?? 0)
    : currentFetcherData?.amountOfCommits

  const lastChanged = isBlob ? databaseInfo.lastChanged[clickedObject.path] : currentFetcherData?.lastChanged
  const contributorCount = currentFetcherData?.contributors?.length

  const metrics: Record<
    MetricType,
    {
      description: string
      icon: string
      data: string
    }
  > = {
    FILE_TYPE: {
      description: isTree(clickedObject) ? "Folder type" : "File type",
      icon: isRepo ? mdiSourceRepository : isBlob ? mdiFileOutline : mdiFolderOutline,
      data: isRepo ? "Repository" : isBlob ? "." + last(clickedObject.name.split(".")) : "Directory"
    },
    FILE_SIZE: {
      description: clickedObject.type === "tree" ? "Folder size" : "File size",
      icon: FileSizeMetric.icon,
      data: (() => {
        return byteSize(clickedObject.byteSize).value + " " + byteSize(clickedObject.byteSize).unit
      })()
    },
    MOST_COMMITS: {
      description: commitCount === 1 ? "Commit" : "Commits",
      icon: CommitsMetric.icon,
      data: formatMetricCount(commitCount)
    },
    MOST_CONTRIBUTIONS: {
      description: "Line Changes",
      icon: LinesChangedMetric.icon,
      data: formatMetricCount(contributions)
    },
    CONTRIBUTORS: {
      icon: ContributorsMetric.icon,
      description: "Contributors",
      data: formatMetricCount(contributorCount)
    },
    TOP_CONTRIBUTOR: {
      description: currentFetcherData?.multiTopContributors ? "Top Churners" : "Top Churner",
      icon: TopContributorMetric.icon,
      data: formatTopContributorSummary(currentFetcherData)
    },
    LAST_CHANGED: {
      description: "Last change",
      icon: LastChangedMetric.icon,
      data: formatLastChangedSummary(lastChanged, selectedRangeMetricsLoaded)
    }
  } as const

  return (
    <>
      <GroupContributorsModal open={modalOpen} onClose={() => setModalOpen(false)} />
      <div className="grid grid-cols-2 gap-2">
        {(Object.entries(metrics) as Array<[MetricType, (typeof metrics)[MetricType]]>).map(
          ([metric, { icon, data, description }]) => (
            <MetricButton
              key={metric}
              icon={icon}
              isCurrentMetric={metric === metricType}
              color={objectColor && metric === metricType ? objectColor : undefined}
              onClick={() => void setMetricType(metric)}
            >
              <p className="truncate text-xs font-normal opacity-70">{description}</p>
              <p className="w-full truncate text-sm font-bold" title={data}>
                {data}
              </p>
            </MetricButton>
          )
        )}
      </div>
    </>
  )
}

function MetricButton({
  icon,
  isCurrentMetric,
  children,
  color,
  onClick
}: {
  icon: string
  isCurrentMetric: boolean
  children: ReactNode
  color?: HexColor
  onClick?: () => void
}) {
  const fadedColor = `hsl(from var(--color, var(--metric-button-bg)) h s l / var(--brightness))`

  return (
    <button
      type="button"
      className={cn(
        "border-border flex h-full w-full cursor-pointer flex-row items-center justify-between gap-5 rounded border bg-(--bg) px-2 py-1 shadow-sm transition-colors [--brightness:1] [--metric-button-bg:var(--color-secondary-bg)] hover:[--brightness:0.6] dark:[--metric-button-bg:var(--color-secondary-bg-dark)]",
        {
          "ring-primary ring-1": isCurrentMetric
        }
      )}
      style={
        {
          "--color": color,
          "--bg": fadedColor,
          color: `contrast-color(var(--bg))`
        } as CSSProperties
      }
      onClick={onClick}
    >
      <Icon path={icon} size={0.75} />
      <div className="flex flex-col overflow-hidden text-right">{children}</div>
    </button>
  )
}

const LOADING_LABEL = "loading..."
const NO_ACTIVITY_LABEL = "No activity"

export function formatTopContributorSummary(
  data: Pick<ClickedObjectInfo, "multiTopContributors" | "topContributor"> | null | undefined
) {
  if (!data) {
    return LOADING_LABEL
  }

  if (data.multiTopContributors) {
    return "Multiple people"
  }

  return data.topContributor[0]?.contributor ?? "No contributors"
}

export function formatMetricCount(value: number | null | undefined) {
  return value == null ? LOADING_LABEL : value.toLocaleString()
}

export function formatLastChangedSummary(epochTimeSecs: number | null | undefined, dataLoaded: boolean) {
  if (epochTimeSecs === undefined || epochTimeSecs === null || epochTimeSecs <= 0) {
    return dataLoaded ? NO_ACTIVITY_LABEL : LOADING_LABEL
  }

  const relativeDate = dateFormatRelative(epochTimeSecs)
  return relativeDate ? `${relativeDate} ago` : UNKNOWN_CATEGORY
}

