export const ErrorBoundary = () => {
  const { pathname, search } = useLocation()
  const error = useRouteError()

  const mainProcessClosed = error instanceof Error && error.message.startsWith("Failed to fetch")
  const message = mainProcessClosed
    ? "Git Truck is not running, please start it and try again."
    : "Oh no, the Git Truck crashed!"

  const url = new URL("https://github.com/git-truck/git-truck/issues/new?template=bug.yml")
  url.searchParams.append("title", "crash: " + (error instanceof Error ? error.message : "Unknown error"))
  url.searchParams.append("os", navigator.platform)
  url.searchParams.append("version", pkg.version)
  if (error && error instanceof Error) url.searchParams.append("description", `\n\n\`\`\`\n${error.stack}\n\`\`\``)

  return (
    <Shell>
      <ErrorPage className="min-h-screen" message={message} truck={mainProcessClosed ? "parked" : "crashed"}>
        <div className="flex flex-wrap justify-center gap-2">
          <Link reloadDocument className="btn" to={pathname + search}>
            Retry
          </Link>
          {!mainProcessClosed ? (
            <>
              <Link className="btn btn--primary" to="..">
                Go back
              </Link>
              <ClearCacheForm redirectPath={pathname + search} />
              <a href={url.toString()} target="_blank" rel="noopener noreferrer" className="btn btn--secondary">
                <Icon path={mdiAlertOutline} />
                Report issue
              </a>
            </>
          ) : null}
        </div>
        {!mainProcessClosed ? (
          <div className="mx-auto w-2xl space-y-2">
            <CollapsibleHeader className="card" title={() => "Error"} defaultOpen={false}>
              <Code className="overflow-x-auto border-0 text-left whitespace-pre">
                {error instanceof Error ? error.stack : "No stack trace available"}
              </Code>
            </CollapsibleHeader>
          </div>
        ) : null}
      </ErrorPage>
    </Shell>
  )
}

import { href, useFetcher } from "react-router"
import clsx from "clsx"
import type React from "react"
import { useEffect, useMemo } from "react"
import type { AnalysisStatus } from "~/server/Analysis"
import drivingTruck from "~/assets/drivingTruck_48x.gif"
import loadingTruck from "~/assets/loadingTruck_48x.gif"
import unloadingTruck from "~/assets/unloadingTruck_48x.gif"
import crashedTruck from "~/assets/crashedTruck_48x.gif"
import { cn } from "~/styling"
import { useQueryState } from "nuqs"
import { progressSerializer } from "~/routes/api.progress"

export type ProgressData = {
  progress: number
  analysisStatus: AnalysisStatus
  progressRevision?: number
}

const PROGRESS_POLL_INTERVAL_MS = 1000

export function LoadingIndicator({
  className = "",
  showProgress = false,
  fetchProgress = true,
  loadingText: LoadingText
}: {
  loadingText?: React.FC<{ status: AnalysisStatus }>
  showProgress?: boolean
  fetchProgress?: boolean
  className?: string
}) {
  const [path] = useQueryState("path")
  const [branch] = useQueryState("branch")

  const { load, data, state } = useFetcher<ProgressData>()

  useEffect(() => {
    if (
      !showProgress ||
      !fetchProgress ||
      !path ||
      !branch ||
      state !== "idle" ||
      data?.analysisStatus === "Aborted" ||
      data?.analysisStatus === "CommitHistoryProcessed"
    )
      return

    const timeoutId = window.setTimeout(() => {
      load(href("/api/progress") + progressSerializer({ path, branch, lastSeenRevision: data?.progressRevision ?? -1 }))
    }, PROGRESS_POLL_INTERVAL_MS)

    return () => {
      window.clearTimeout(timeoutId)
    }
  }, [branch, fetchProgress, state, path, showProgress, data?.progressRevision, load, data?.analysisStatus])

  const [progressText, progress, gif] = useMemo<[string, number, string]>(() => {
    if (!data) return ["Loading truck...", 0, loadingTruck]
    const { progress, analysisStatus: analyzationStatus } = data

    switch (analyzationStatus) {
      case "Initialized":
        return ["Loading truck...", 0, loadingTruck]
      case "CommitHistoryProcessed":
        return ["Unloading truck...", 0, unloadingTruck]
      case "Aborted":
        return ["Aborted", 0, crashedTruck]
      case "ProcessingCommitHistory":
        return progress < 100
          ? ["Driving to destination...", progress, drivingTruck]
          : ["Unloading truck...", progress, unloadingTruck]
    }
  }, [data])

  return (
    <div className={clsx("grid h-full w-full place-items-center px-4", className)}>
      <div className="flex w-full max-w-[clamp(16rem,80vw,36rem)] flex-col gap-4 px-2 py-2">
        <img src={showProgress ? gif : drivingTruck} alt="🚛" className="pixelated aspect-square w-full" />
        {showProgress ? <div className="text-center text-3xl font-bold">{progressText}</div> : null}
        {showProgress && data?.analysisStatus !== "Aborted" ? (
          <div
            className={cn("h-6 w-3/4 self-center rounded-2xl bg-gray-300 transition-opacity", {
              "opacity-0": !progress
            })}
          >
            <div
              className={cn(
                "bg-blue-primary h-[calc(100%-4px)] min-w-[calc(var(--spacing)*6-4px)] translate-x-0.5 translate-y-0.5 rounded-2xl transition-[width] duration-1000 ease-in-out"
              )}
              style={{ width: progress ? `calc(${Math.min(progress, 100)}% - 4px)` : "40px" }}
            />
          </div>
        ) : null}
        {LoadingText ? (
          <div className="text-center">
            <LoadingText status={data?.analysisStatus ?? "Initialized"} />
          </div>
        ) : null}
      </div>
    </div>
  )
}

import { mdiChevronDoubleRight, mdiChevronRight, mdiSourceRepository, mdiSourceRepositoryMultiple } from "@mdi/js"
import { Icon } from "~/components/Icon"
import { useMemo, Fragment } from "react"
import { cn } from "~/styling"
import { useQueryStates } from "nuqs"
import { href, Link } from "react-router"
import { viewSearchParamsConfig } from "~/shared/viewParams"
import { useDataNullable } from "~/contexts/DataContext"
import { getSep } from "~/shared/util"
import { AnalysisInfo } from "~/components/GlobalInfo"
import { browseSearchParamsConfig, browseSerializer } from "~/routes/browse"
import { useClickedObjectNullable, useSetClickedObjectPath } from "~/state/stores/clicked-object"
import { ClickedObjectButton } from "~/components/buttons/ClickedObjectButton"

type Segment = {
  type: "browse" | "zoom" | "filler" | "clicked"
  segment: string
  fullPath: string
  parentPath: string
  showAnalysisInfo: boolean
}

export function Breadcrumb({ className = "", zoom = false }: { className?: string; zoom?: boolean }) {
  const [browseParams] = useQueryStates(browseSearchParamsConfig)
  const [viewParams, setViewParams] = useQueryStates(viewSearchParamsConfig)
  const setClickedObjectPath = useSetClickedObjectPath()
  const { path, zoomPath } = viewParams
  const data = useDataNullable()
  const clickedObject = useClickedObjectNullable()
  const clickedObjectIsZoomPath = clickedObject?.path === zoomPath

  const breadcrumbSegments = useMemo<Array<Segment>>(() => {
    if (!path) return []

    const pathSegments = path
      .split(getSep(path))
      .map((segment, i, segments) => {
        const fullPath = segments.slice(0, i + 1).join("/")
        return {
          type: "browse",
          segment: segment.length === 0 && i === 0 ? "/" : segment,
          fullPath: i === 0 ? fullPath + getSep(path) : fullPath,
          parentPath: i === 0 ? "" : segments.slice(0, i).join("/"),
          showAnalysisInfo: false
        } satisfies Segment
      })
      .filter((segment) => segment.segment.length > 0)

    const zoomSegments = !data
      ? []
      : [
          // Parent folder
          {
            type: "browse",
            segment: data.repo.parentDirName ?? "",
            fullPath: data.repo.parentDirPath ?? "",
            parentPath: "",
            showAnalysisInfo: false
          } as const,
          // Repository root
          {
            type: "zoom",
            segment: data.repo.repositoryName,
            fullPath: data.repo.repositoryName,
            parentPath: data.repo.repositoryName,
            showAnalysisInfo: true
          } as const,
          ...(zoomPath?.split(getSep(zoomPath)) ?? []).flatMap((segment, index, segments) => {
            if (segment === data?.repo.repositoryName) {
              // Ignore repository root, as it is added manually above
              return []
            }
            const fullPath = segments.slice(0, index + 1).join("/")
            const parentPath = index > 0 ? segments.slice(0, index).join("/") : ""
            return { type: "zoom", segment, fullPath, parentPath, showAnalysisInfo: false } satisfies Segment
          })
        ]
    const segments = zoom ? zoomSegments : pathSegments

    if (segments.length > 4) {
      return [
        segments[0],
        segments[1],
        { type: "filler", segment: "...", fullPath: "", parentPath: "", showAnalysisInfo: false } satisfies Segment,
        segments[segments.length - 2],
        segments[segments.length - 1]
      ] satisfies Array<Segment>
    }

    return segments
  }, [data, path, zoom, zoomPath])

  return (
    <div
      className={cn(
        "text-secondary-text dark:text-secondary-text-dark flex h-8 min-w-0 items-center justify-stretch gap-1 overflow-x-auto",
        className
      )}
    >
      {breadcrumbSegments.map(({ type, segment, fullPath, parentPath, showAnalysisInfo: isRepo }, i) => {
        const title = isRepo
          ? "Reset zoom to repository root"
          : type === "browse"
            ? `Browse ${segment} directory`
            : clickedObjectIsZoomPath
              ? "Zoom to parent"
              : `Zoom to ${segment} directory`
        const isFirst = i === 0

        const content = (
          <>
            {isRepo ? (
              <Icon path={mdiSourceRepository} />
            ) : zoom && type === "browse" ? (
              <Icon path={mdiSourceRepositoryMultiple} />
            ) : null}
            <span className="min-w-0 truncate">{segment}</span>
          </>
        )
        const button =
          type === "filler" ? (
            <div
              title={fullPath}
              className="text-tertiary-text dark:text-tertiary-text-dark pointer-events-none flex w-max items-center gap-2 overflow-hidden text-sm font-bold opacity-80"
            >
              {content}
            </div>
          ) : type === "browse" ? (
            <Link
              to={href("/browse") + browseSerializer({ ...browseParams, offset: 0, search: null, path: fullPath })}
              title={title}
              className="text-secondary-text dark:text-secondary-text-dark flex min-w-0 cursor-pointer items-center gap-1 overflow-hidden text-sm font-bold"
              onClick={() => setClickedObjectPath(null)}
            >
              {content}
            </Link>
          ) : (
            <button
              title={title}
              className="text-secondary-text dark:text-secondary-text-dark flex min-w-0 cursor-pointer items-center gap-1 overflow-hidden text-sm font-bold"
              onClick={() => {
                if (!data) {
                  throw Error("Attempting to access data when none is loaded")
                }
                if (zoomPath === fullPath) {
                  if (clickedObjectIsZoomPath) {
                    setViewParams((prev) => ({ ...prev, zoomPath: parentPath }))
                    return
                  } else {
                    setClickedObjectPath(null)
                    return
                  }
                }
                setViewParams((prev) => ({ ...prev, zoomPath: fullPath }))
              }}
            >
              {content}
            </button>
          )

        return (
          <Fragment key={fullPath}>
            {!isFirst ? <Icon path={mdiChevronRight} size="1.25rem" /> : null}
            {isRepo ? (
              <AnalysisInfo className="min-w-0" trigger={button} triggerClassName="min-w-0 overflow-hidden" />
            ) : (
              button
            )}
          </Fragment>
        )
      })}

      {clickedObject && clickedObject.path !== zoomPath && clickedObject.path !== data?.repo.repositoryName ? (
        <>
          <Icon path={mdiChevronDoubleRight} className="mx-1" size="1.25rem" />
          <ClickedObjectButton />
        </>
      ) : null}
    </div>
  )
}

import { mdiMagnify, mdiMagnifyMinusOutline } from "@mdi/js"
import { useQueryState, useQueryStates } from "nuqs"
import { Link, useLocation } from "react-router"
import { Icon } from "~/components/Icon"
