import { DropdownMenu } from "radix-ui"
import { mdiClose, mdiDotsVertical, mdiInformation, mdiMagnify } from "@mdi/js"
import { useState, useRef, type ReactNode, createContext, use } from "react"
import { ExpandingPanelButton } from "~/components/buttons/ExpandingPanelButton"
import { Icon } from "~/components/Icon"
import { useHasSelection, useResetSelection } from "~/state/stores/selection"
import { cn } from "~/styling"

const MetricSearchContext = createContext<{ searchValue: string; onSearchChange: (value: string) => void }>({
  searchValue: "",
  onSearchChange: () => {}
})

export function useMetricSearchContext() {
  return use(MetricSearchContext)
}

export type MetricPanelButton = {
  search?: boolean
  clear?: boolean
}

export type MetricPanelDropdownButton = {
  icon: string
  label: string
  onClick: () => void
}

export function MetricInspectionPanel({
  className = "",
  title,
  children,
  actions = { search: false, clear: false },
  metricMenuItems = [],
  description = "Description not provided."
}: {
  className?: string
  title?: ReactNode
  children: ReactNode
  actions?: MetricPanelButton
  metricMenuItems: MetricPanelDropdownButton[]
  description: string
}) {
  const [selectedSearch, setSelectedSearch] = useState("")
  const [infoOpen, setInfoOpen] = useState(true)

  return (
    <div className={cn("flex w-full flex-col gap-0", className)}>
      {title ? (
        <div className="flex w-full flex-row items-end justify-between align-bottom">
          <button
            className="btn btn--primary border-border dark:border-border-dark flex shrink-0 flex-row items-center gap-2 rounded-t-lg rounded-b-none border-2 p-2"
            title={"Toggle description"}
            onClick={() => setInfoOpen(!infoOpen)}
          >
            <span className="text-sm font-bold">{title}</span>
            {!infoOpen ? (
              <Icon path={mdiInformation} size="1.25em" className="fill-bg-primary dark:fill-bg-primary-dark ml-auto" />
            ) : null}
          </button>

          <div className="flex h-full flex-row gap-1 justify-self-end align-bottom">
            {actions.search ? <SearchButton value={selectedSearch} onChange={setSelectedSearch} /> : null}
            {actions.clear ? <ClearSelectionButton /> : null}
            {metricMenuItems.length > 0 ? <SettingsButton metricMenuItems={metricMenuItems} /> : null}
          </div>
        </div>
      ) : null}
      <div
        className={cn("bg-primary-bg dark:bg-primary-bg-dark -mt-0.5 rounded-b-lg", {
          "border-border dark:border-border-dark space-y-4 border-2 p-2": title
        })}
      >
        {infoOpen ? (
          <div className="border-blue-primary bg-blue-secondary/30 mt-2 w-full rounded-lg border-2 py-2">
            <div className="flex h-full flex-row items-center">
              <Icon path={mdiInformation} size="1.25em" className="fill-bg-primary dark:fill-bg-primary-dark mx-2" />
              <div className="h-full w-full items-center">
                <p className="text-secondary-text dark:text-secondary-text-dark text-xs font-medium">{description}</p>
              </div>
              <button className="btn btn--text" onClick={() => setInfoOpen(false)}>
                <Icon path={mdiClose} size="1.25em" className="fill-bg-primary dark:fill-bg-primary-dark" />
              </button>
            </div>
          </div>
        ) : null}
        <div className="mt-2">
          <MetricSearchContext value={{ searchValue: selectedSearch, onSearchChange: setSelectedSearch }}>
            {children}
          </MetricSearchContext>
        </div>
      </div>
    </div>
  )
}

function ClearSelectionButton() {
  const resetSelection = useResetSelection()
  const hasSelection = useHasSelection()

  return (
    <ExpandingPanelButton
      disabled={!hasSelection}
      icon={mdiClose}
      danger={hasSelection}
      expanded={hasSelection}
      onClick={resetSelection}
    >
      Clear
    </ExpandingPanelButton>
  )
}

function SettingsButton({ metricMenuItems }: { metricMenuItems: MetricPanelDropdownButton[] }) {
  return (
    <>
      <DropdownMenu.Root>
        <DropdownMenu.Trigger asChild disabled={metricMenuItems.length === 0}>
          <button
            disabled={metricMenuItems.length === 0}
            aria-label="Panel options"
            title="Panel options"
            className="btn border-border dark:border-border-dark flex shrink-0 flex-row items-center gap-2 rounded-t-lg rounded-b-none border-2 p-2"
          >
            <Icon path={mdiDotsVertical} size="1em" />
          </button>
        </DropdownMenu.Trigger>
        <DropdownMenu.Content
          align="end"
          alignOffset={5}
          className="bg-primary-bg dark:bg-primary-bg-dark border-border dark:border-border-dark z-1 -mt-0.5"
        >
          <DropdownMenu.Arrow className="fill-border dark:fill-border-dark" />
          {metricMenuItems.map((item, index) => (
            <DropdownMenu.Item
              key={index}
              className={cn(
                "btn -mt-0.5 flex cursor-pointer flex-row items-center justify-start rounded-none px-2 py-1 text-sm hover:bg-gray-200 dark:hover:bg-gray-700",
                {
                  "rounded-t-lg": index === 0,
                  "rounded-b-lg": index === metricMenuItems.length - 1
                }
              )}
              onSelect={item.onClick}
            >
              <Icon path={item.icon} size="1em" />
              {item.label}
            </DropdownMenu.Item>
          ))}
        </DropdownMenu.Content>
      </DropdownMenu.Root>
    </>
  )
}

function SearchButton({ value, onChange }: { value: string; onChange: (value: string) => void }) {
  const ref = useRef<HTMLInputElement>(null)

  return (
    <div className="group flex w-fit items-center gap-0">
      <span
        className={cn(
          "btn flex items-center justify-start gap-0 overflow-hidden rounded-t-lg rounded-b-none px-2 transition-all duration-200",
          value ? "w-auto" : "w-fit max-w-fit group-hover:w-auto"
        )}
        tabIndex={-1}
      >
        <Icon path={mdiMagnify} size="1em" />
        <input
          ref={ref}
          type="text"
          placeholder={`Search…`}
          value={value}
          className={cn(
            "bg-transparent text-sm transition-all duration-200 outline-none",
            value ? "ml-2 w-20" : "w-0 group-hover:ml-2 group-hover:w-20 focus:ml-2 focus:w-20"
          )}
          onChange={(e) => onChange(e.target.value)}
          onKeyDown={(evt) => {
            if (evt.key === "Escape") {
              evt.currentTarget.blur()
              evt.stopPropagation()
            }
          }}
        />
        <button
          type="button"
          disabled={!value}
          className={cn(
            "overflow-hidden rounded transition-all duration-200",
            value
              ? "ml-2 w-auto p-0.5 opacity-100 hover:bg-gray-200 dark:hover:bg-gray-700"
              : "ml-0 w-0 cursor-not-allowed opacity-0"
          )}
          title="Clear search"
          onClick={() => {
            onChange("")
            if (document.activeElement === ref.current) {
              ref.current?.focus()
            }
          }}
        >
          <Icon path={mdiClose} size="0.75em" />
        </button>
      </span>
    </div>
  )
}

import type { DatabaseInfo, GitBlobObject, GitObject, RawGitObject, HexColor, Person, RepoData } from "~/shared/model"
import type { GradLegendData } from "~/components/legend/GradiantLegend"
import { type PointLegendData } from "~/components/legend/PointLegend"
import type { SegmentLegendData } from "~/components/legend/SegmentLegend"
import { TopContributorMetric } from "~/metrics/topContributer"
import { TypeMetric } from "~/metrics/fileExtension"
import { LastChangedMetric } from "~/metrics/lastChanged"
import { CommitsMetric } from "~/metrics/mostCommits"
import { LinesChangedMetric } from "~/metrics/linesChanged"
import { scaleOrdinal } from "d3"
import sha1 from "sha1"
import type { SizeMetricType } from "~/metrics/sizeMetric"
import { FileSizeMetric } from "~/metrics/fileSize"
import { ContributorsMetric } from "./contributors"
import type { ReactNode } from "react"
import type { MetricPanelButton } from "~/components/inspection/MetricInspectionPanel"
import { categoricalScheme } from "~/const"

/**
 * Defines the available metrics in the application
 *
 * This is the single source of truth for all metrics
 */

export const Metrics = {
  LAST_CHANGED: LastChangedMetric,
  FILE_TYPE: TypeMetric,
  FILE_SIZE: FileSizeMetric,
  MOST_COMMITS: CommitsMetric,
  MOST_CONTRIBUTIONS: LinesChangedMetric,
  TOP_CONTRIBUTOR: TopContributorMetric,
  CONTRIBUTORS: ContributorsMetric
} as const satisfies Record<string, Metric>

export type CategoricalMetricType = "FILE_TYPE" | "TOP_CONTRIBUTOR" | "CONTRIBUTORS"

export const mapMetricToCategoryNoun: Record<CategoricalMetricType, string> = {
  CONTRIBUTORS: "contributors",
  TOP_CONTRIBUTOR: "contributors",
  FILE_TYPE: "file types"
}

type Metric = {
  name: string
  description: string
  icon: string
  inspectionPanels: MetricPanelConfig[]
  getTooltipContent: (
    /**
     * The hovered objectGitObject
     */
    obj: GitObject,
    /**
     * Data from the server
     */
    dbi: DatabaseInfo,
    options: {
      topContributorCutoff: number
      contributorColors: Record<string, HexColor>
    }
  ) => ReactNode
  metricFunctionFactory: (
    data: RepoData,
    root: GitObject,
    options: { contributorColors: Record<string, HexColor>; topContributorCutoff: number }
  ) => MetricFunction
}

export const isContributorMetric = (metricType: MetricType): boolean =>
  metricType === "CONTRIBUTORS" || metricType === "TOP_CONTRIBUTOR"

export type CategoricalMetric = Metric & {
  getCategories: (obj: GitObject, dbi: DatabaseInfo, options: { topContributorCutoff: number }) => string[]
}

export type SegmentedMetric = CategoricalMetric & {
  getBuckets(dbi: DatabaseInfo): SegmentBucket[]
  getBucketIndex(obj: RawGitObject, dbi: DatabaseInfo, buckets?: readonly SegmentBucket[]): number
}

export type SegmentBucket = {
  text: string
  range: [number, number]
  color: HexColor
}

export type GradientedMetric = Metric & {
  getColorFromValue: (value: number, dbi: DatabaseInfo, cache: MetricCache) => HexColor
  getColorFromObject: (obj: RawGitObject, dbi: DatabaseInfo, cache: MetricCache) => HexColor
}

//Metric Panel Types
export type MetricPanelActionId = "group-contributors" | "shuffle-colors" | "toggle-top-contributor-slider"

export type MetricPanelDropdownButtonConfig = {
  icon: string
  label: string
  actionId: MetricPanelActionId
}

type MetricPanelConfig = {
  id: string
  title?: string
  content: React.ComponentType
  description: string
  actions?: MetricPanelButton
  menuItems?: MetricPanelDropdownButtonConfig[]
}

export type MetricType = keyof typeof Metrics

type MetricFunction = (blob: GitBlobObject, cache: MetricCache) => void

export type MetricsData = {
  caches: Map<MetricType, MetricCache>
  contributorColorMap: Map<string, string>
}

export function createMetricData(
  data: RepoData,
  colorSeed: string | null,
  predefinedContributorColors: Record<string, HexColor>,
  topContributorCutoff: number
): MetricsData {
  return createMetricDataForNode(
    data,
    data.databaseInfo.fileTree,
    colorSeed,
    predefinedContributorColors,
    topContributorCutoff
  )
}

export function createMetricDataForNode(
  data: RepoData,
  root: GitObject,
  colorSeed: string | null,
  predefinedContributorColors: Record<string, HexColor>,
  topContributorCutoff: number
): MetricsData {
  const contributorColors = generateContributorColors(
    data.databaseInfo.contributors,
    colorSeed,
    predefinedContributorColors
  )

  return {
    caches: setupMetricsCache(root, getMetricCalcs(data, root, contributorColors, topContributorCutoff)),
    contributorColorMap: new Map(Object.entries(contributorColors))
  }
}

export const sizeMetricDescriptions: Record<SizeMetricType, string> = {
  FILE_SIZE: "Files are sized based on their file size in bytes.",
  EQUAL_SIZE: "All files are sized equally.",
  MOST_COMMITS: "Files are sized based on the number of commits in the selected time range.",
  LAST_CHANGED: "Files are sized based on how long ago they were changed.",
  MOST_CONTRIBUTIONS: "Files are sized based on how many line changes (additions and deletions) have been made to it."
}

export type MetricCache = {
  legend: PointLegendData | GradLegendData | SegmentLegendData | undefined
  buckets?: readonly SegmentBucket[]
  categoriesMap: Map<string, Array<{ category: string; color: HexColor }>>
}

function generateContributorColors(
  contributors: Person[],
  colorSeed: string | null,
  predefinedContributorColors: Record<string, HexColor>
): Record<string, HexColor> {
  const contributorColorMap: Record<string, HexColor> = {}
  const colors = scaleOrdinal(categoricalScheme).range()

  const sortedContributors = contributors
    .map((contributor) => contributor.name)
    .sort((a, b) => sha1(a + colorSeed).localeCompare(sha1(b + colorSeed)))

  for (let i = 0; i < sortedContributors.length; i++) {
    const contributor = sortedContributors[i]
    const existing = predefinedContributorColors[contributor]
    if (existing) {
      contributorColorMap[contributor] = existing
      continue
    }
    const color = colors[i % colors.length] as HexColor
    contributorColorMap[contributor] = color
  }
  return contributorColorMap
}

function getMetricCalcs(
  data: RepoData,
  root: GitObject,
  contributorColors: Record<string, HexColor>,
  topContributorCutoff: number
): Record<MetricType, MetricFunction> {
  const options = { contributorColors, topContributorCutoff }
  return {
    FILE_TYPE: TypeMetric.metricFunctionFactory(data, root, options),
    MOST_COMMITS: CommitsMetric.metricFunctionFactory(data, root, options),
    LAST_CHANGED: LastChangedMetric.metricFunctionFactory(data, root, options),
    TOP_CONTRIBUTOR: TopContributorMetric.metricFunctionFactory(data, root, options),
    MOST_CONTRIBUTIONS: LinesChangedMetric.metricFunctionFactory(data, root, options),
    FILE_SIZE: FileSizeMetric.metricFunctionFactory(data, root, options),
    CONTRIBUTORS: ContributorsMetric.metricFunctionFactory(data, root, options)
  }
}

function setupMetricsCache(
  root: GitObject,
  metricCalcs: Record<MetricType, (blob: GitBlobObject, cache: MetricCache) => void>
) {
  const metricCache = new Map<MetricType, MetricCache>()
  setupMetricsCacheRec(root, metricCalcs, metricCache)
  return metricCache
}

function setupMetricsCacheRec(
  root: GitObject,
  metricCalcs: Record<MetricType, MetricFunction>,
  acc: Map<MetricType, MetricCache>
) {
  if (root.type === "blob") {
    const entries = Object.entries(metricCalcs) as [MetricType, MetricFunction][]
    for (const [metricType, metricFunc] of entries) {
      if (!acc.has(metricType)) {
        acc.set(metricType, {
          legend: undefined,
          categoriesMap: new Map<string, Array<{ category: string; color: `#${string}` }>>()
        })
      }
      metricFunc(
        root,
        acc.get(metricType) ?? {
          legend: undefined,
          categoriesMap: new Map<string, Array<{ category: string; color: `#${string}` }>>()
        }
      )
    }
    return
  }

  for (const child of root.children) {
    switch (child.type) {
      case "tree":
        setupMetricsCacheRec(child, metricCalcs, acc)
        break
      case "blob": {
        const entries = Object.entries(metricCalcs) as [MetricType, MetricFunction][]
        for (const [metricType, metricFunc] of entries) {
          if (!acc.has(metricType)) {
            acc.set(metricType, {
              legend: undefined,
              categoriesMap: new Map<string, Array<{ category: string; color: `#${string}` }>>()
            })
          }
          metricFunc(
            child,
            acc.get(metricType) ?? {
              legend: undefined,
              categoriesMap: new Map<string, Array<{ category: string; color: `#${string}` }>>()
            }
          )
        }
        break
      }
    }
  }
}

import { mdiFlaskOutline, mdiArrowUpBoldCircleOutline } from "@mdi/js"
import { Icon } from "~/components/Icon"
import { generateVersionComparisonLink } from "~/shared/util"
import { Code } from "~/components/util"
import { Popover } from "~/components/Popover"
import { cn } from "~/styling"

export function UpdateNotifier({
  installedVersion,
  latestVersion
}: {
  installedVersion: string
  latestVersion: string | null
}) {
  const isExperimental = installedVersion.includes("0.0.0")

  return (
    <Popover
      popoverTitle={isExperimental ? "Experimental version" : `Update available`}
      trigger={({ onClick }) => {
        const title = isExperimental ? "You are using an experimental version" : `Version ${latestVersion} available`
        const iconPath = isExperimental ? mdiFlaskOutline : mdiArrowUpBoldCircleOutline
        const showIndicator = !isExperimental

        return (
          <button
            title={title}
            className={cn(
              "aspect-square",
              isExperimental ? "btn text-primary-text-dark bg-purple-500" : "btn relative self-center rounded-full p-1"
            )}
            onClick={onClick}
          >
            {showIndicator && (
              <div className="absolute top-0.5 right-0.5 size-2 rounded-full border border-green-400 bg-green-600" />
            )}
            <Icon path={iconPath} size="1.25em" />
          </button>
        )
      }}
    >
      {isExperimental ? (
        <>
          <p>You are using an experimental build of Git Truck</p>
          <p className="text-sm">If you want to use the stable version, close the application and run: </p>
        </>
      ) : (
        <>
          <p>
            {latestVersion ? (
              <a
                className="text-blue-500 hover:underline"
                href={generateVersionComparisonLink({
                  currentVersion: installedVersion,
                  latestVersion: latestVersion
                })}
                target="_blank"
                rel="noopener noreferrer"
                title="See what's new"
              >
                Git Truck v{latestVersion} is now available!
              </a>
            ) : null}{" "}
          </p>
          <p className="text-sm">To update, run</p>
        </>
      )}
      {/* TODO: Detect runtime: global install, npx, bunx, etc. and suggest appropriate update command */}
      <Code inline>npm install -g git-truck@latest</Code>
    </Popover>
  )
}

import { useFetcher, useNavigation, href } from "react-router"
import { Fragment, useCallback, useEffect, useState, useTransition } from "react"
import { Slider, Handles, Tracks } from "react-compound-slider"
import { useData } from "~/contexts/DataContext"
import { cn } from "~/styling"
import { BarChart } from "~/components/BarChart"
import { TimelineHeader } from "~/components/Timeline/TimelineHeader"
import {
  mdiAccountMultiple,
  mdiCheckboxBlankOutline,
  mdiCheckboxMarkedOutline,
  mdiDotsVertical,
  mdiMathLog
} from "@mdi/js"
import { Icon } from "~/components/Icon"

import type { TimeUnit } from "~/shared/utils/time"
import { useQueryState, useQueryStates } from "nuqs"
import { viewSearchParamsConfig, viewSerializer } from "~/shared/viewParams"

import { expandIntervalToRange } from "~/shared/util"
import type { loader } from "~/routes/api.commit-intervals"
import { useClickedObjectPath } from "~/state/stores/clicked-object"

type TimeIntervalRef = { timestamp: number }

function timeToSliderUnit(
  timestampSecs: number,
  intervals: TimeIntervalRef[],
  unit: TimeUnit,
  handle: "start" | "end"
) {
  if (intervals.length === 0) return 0

  for (let i = 0; i < intervals.length; i++) {
    const [, end] = expandIntervalToRange(intervals[i].timestamp, unit)

    if (handle === "end") {
      if (timestampSecs <= end) return i + 1
    } else {
      if (timestampSecs < end) return i
    }
  }

  return intervals.length
}

function sliderUnitsToTimeRange({
  startIndex,
  endIndex,
  intervals,
  unit,
  minSecs,
  maxSecs
}: {
  startIndex: number
  endIndex: number
  intervals: TimeIntervalRef[]
  unit: TimeUnit
  minSecs: number
  maxSecs: number
}): [number, number] {
  if (intervals.length === 0) return [minSecs, maxSecs]

  const clampedStartIndex = Math.max(0, Math.min(startIndex, intervals.length - 1))
  const clampedEndIndex = Math.max(0, Math.min(endIndex - 1, intervals.length - 1))
  const [start] = expandIntervalToRange(intervals[clampedStartIndex].timestamp, unit)
  const [, end] = expandIntervalToRange(intervals[clampedEndIndex].timestamp, unit)

  return [Math.max(minSecs, start), Math.min(maxSecs, end)]
}

export function Timeline({ className }: { className?: string }) {
  const [includeCoAuthors, setIncludeCoAuthors] = useQueryState(
    "includeCoauthors",
    viewSearchParamsConfig.includeCoauthors
  )
  const [commitCountScale, setCommitCountScale] = useState<"linear" | "log">("log")
  const { databaseInfo } = useData()
  const { timerange } = databaseInfo
  const [rangeMin, rangeMax] = timerange
  const [{ start: low, end: high }] = useQueryStates({
    start: viewSearchParamsConfig.start.withDefault(rangeMin),
    end: viewSearchParamsConfig.end.withDefault(rangeMax)
  })

  const unit = databaseInfo.commitCountPerTimeIntervalUnit

  const navigationData = useNavigation()
  const disabled = navigationData.state !== "idle"

  const { data, load } = useFetcher<typeof loader>()

  const clickedObjectPath = useClickedObjectPath()

  const [{ path, branch, start, end }] = useQueryStates({
    start: viewSearchParamsConfig.start,
    end: viewSearchParamsConfig.end,
    objectPath: viewSearchParamsConfig.objectPath,
    path: viewSearchParamsConfig.path,
    branch: viewSearchParamsConfig.branch
  })

  useEffect(() => {
    load(
      href("/api/commit-intervals") +
        viewSerializer({
          objectPath: clickedObjectPath,
          path: path,
          branch,
          start: start ?? rangeMin,
          end: end ?? rangeMax,
          timeUnit: unit,
          includeCoauthors: includeCoAuthors
        })
    )
  }, [branch, clickedObjectPath, end, includeCoAuthors, load, path, rangeMax, rangeMin, start, unit])

  const timelineIntervals = databaseInfo.commitCountPerTimeInterval
  const domainInUnits = timelineIntervals.length
  const selectedStartInUnit = timeToSliderUnit(low, timelineIntervals, unit, "start")
  const selectedEndInUnit = timeToSliderUnit(high, timelineIntervals, unit, "end")

  return (
    <div className={cn("card group/card flex flex-col px-4 text-center select-none", className)}>
      <TimelineHeader
        dropdownButtons={[
          {
            icon: mdiMathLog,
            label: (
              <div className="flex w-full items-center justify-between gap-2">
                Use log scale
                <Icon path={commitCountScale === "log" ? mdiCheckboxMarkedOutline : mdiCheckboxBlankOutline} />
              </div>
            ),
            onClick: () => setCommitCountScale((prev) => (prev === "log" ? "linear" : "log"))
          },
          {
            icon: mdiAccountMultiple,
            label: (
              <div className="flex w-full items-center justify-between gap-2">
                Include co-authors <Icon path={includeCoAuthors ? mdiCheckboxMarkedOutline : mdiCheckboxBlankOutline} />
              </div>
            ),
            onClick: () => setIncludeCoAuthors((prev) => !prev)
          }
        ]}
      />
      <div className="group grid">
        <BarChart
          scale={commitCountScale}
          className="grid-full"
          intervals={data?.commitCountPerTimeIntervalForClickedObject ?? []}
        />
        <TimeSlider
          key={[low, high].join("-")}
          startUnits={selectedStartInUnit}
          endUnits={selectedEndInUnit}
          minMs={rangeMin * 1000}
          maxMs={rangeMax * 1000}
          unit={unit}
          domainInUnits={domainInUnits}
          disabled={disabled}
          intervals={timelineIntervals}
        />
      </div>
    </div>
  )
}

function TimeSlider({
  startUnits,
  endUnits,
  minMs,
  maxMs,
  domainInUnits,
  unit,
  disabled,
  intervals
}: {
  startUnits: number
  endUnits: number
  minMs: number
  maxMs: number
  unit: TimeUnit
  domainInUnits: number
  disabled: boolean
  intervals: TimeIntervalRef[]
}) {
  const [isPending, startTransition] = useTransition()
  const [, setStartEnd] = useQueryStates({
    start: viewSearchParamsConfig.start.withOptions({ limitUrlUpdates: { method: "throttle", timeMs: 1000 } }),
    end: viewSearchParamsConfig.end.withOptions({ limitUrlUpdates: { method: "throttle", timeMs: 1000 } })
  })

  const onUpdateSlider = useCallback(
    (e: readonly number[]) => {
      if (e[0] === 0 && e[1] === 0) return

      startTransition(async () => {
        const [startTime, endTime] = sliderUnitsToTimeRange({
          startIndex: e[0],
          endIndex: e[1],
          intervals,
          unit,
          minSecs: minMs / 1000,
          maxSecs: maxMs / 1000
        })
        await setStartEnd({
          start: startTime,
          end: endTime
        })
      })
    },
    [intervals, maxMs, minMs, setStartEnd, unit]
  )

  return (
    <Slider
      className="grid-full pointer-events-none relative"
      mode={3}
      step={1}
      domain={[0, domainInUnits]}
      values={[startUnits, endUnits]}
      disabled={disabled}
      onChange={onUpdateSlider}
    >
      <Handles>
        {({ handles, getHandleProps }) => (
          <Fragment>
            {handles.map((handle) => {
              return (
                <Fragment key={handle.id}>
                  <button
                    key={handle.id}
                    className={cn(
                      "pointer-events-auto absolute bottom-0 z-10 flex h-6 -translate-x-1/2 place-content-center opacity-0 transition-opacity group-hover/card:opacity-100 disabled:grayscale",
                      {
                        "size-5 rounded-full": false
                      },
                      disabled ? "cursor-progress" : "cursor-col-resize"
                    )}
                    role="slider"
                    aria-disabled={disabled}
                    aria-valuemin={0}
                    aria-valuemax={domainInUnits}
                    aria-valuenow={handle.value}
                    title="Drag to adjust interval"
                    style={{
                      left: `${handle.percent}%`
                    }}
                    {...getHandleProps(handle.id)}
                  >
                    <div
                      className={cn(
                        "bg-blue-primary text-primary-text-dark flex h-full w-min items-center rounded-full"
                      )}
                    >
                      <Icon path={mdiDotsVertical} size={0.5} />
                    </div>
                  </button>
                </Fragment>
              )
            })}
          </Fragment>
        )}
      </Handles>
      <Tracks left={false} right={false}>
        {({ tracks, getTrackProps }) => (
          <div>
            {tracks.map(({ id, source, target }) => (
              <div
                key={id}
                className={cn(
                  "bg-blue-primary/20 pointer-events-none absolute right-0 bottom-0 left-0 h-5 cursor-pointer rounded transition-[backdrop-filter]",
                  {
                    "backdrop-blur-2xl": isPending
                  }
                )}
                style={{
                  left: `${source.percent}%`,
                  width: `${target.percent - source.percent}%`
                }}
                {...getTrackProps()}
              />
            ))}
          </div>
        )}
      </Tracks>
    </Slider>
  )
}

import { useId, type SelectHTMLAttributes } from "react"
import type { CompletedResult, GitRefs } from "~/shared/model"
import { mdiSourceBranch } from "@mdi/js"
import { Icon } from "~/components/Icon"
import { cn } from "~/styling"

type GroupedBranchSelectProps = SelectHTMLAttributes<HTMLSelectElement> & {
  headGroups: GitRefs
  analyzedBranches: CompletedResult[]
  iconGroupColorMap?: Record<string, string>
}

export function RevisionSelect({
  headGroups,
  disabled,
  className = "",
  analyzedBranches,
  ...props
}: GroupedBranchSelectProps & SelectHTMLAttributes<HTMLSelectElement>) {
  const id = useId()
  const groupsEntries = Object.entries(headGroups)

  return (
    <div
      title="Change branch"
      className={cn(
        "hover:border-border dark:hover:border-border-dark hover:bg-primary-bg dark:hover:bg-primary-bg-dark flex w-min place-items-center gap-0 rounded-md border-2 border-transparent p-1 transition-colors not-hover:border-transparent not-hover:bg-transparent",
        className
      )}
    >
      <label htmlFor={id}>
        <Icon path={mdiSourceBranch} size={0.75} />
      </label>
      <select className={cn("w-full")} {...props} id={id}>
        {groupsEntries.map(([group, heads]) =>
          Object.entries(heads).length > 0 ? (
            <optgroup key={group} label={group} className="bg-transparent">
              {Object.entries(heads).map(([headName]) => {
                const isAnalyzed = analyzedBranches.find((rep) => rep.branch === headName)
                return (
                  <option
                    key={headName}
                    className="bg-transparent"
                    value={headName}
                    disabled={disabled}
                    title={isAnalyzed ? "Analyzed" : "Not analyzed"}
                  >
                    {headName}
                  </option>
                )
              })}
            </optgroup>
          ) : null
        )}
      </select>
    </div>
  )
}

